import kotlinx.coroutines.*

fun main() = runBlocking {
    val handler = CoroutineExceptionHandler { _, e ->
        println("${e.message} ${e.suppressed.map { it.message }}")
    }
    val job = CoroutineScope(Job() + handler).launch {
        launch {
            try { delay(Long.MAX_VALUE) }
            finally { throw ArithmeticException("second") }
        }
        launch { delay(10); throw IllegalStateException("first") }
    }
    job.join()
}

